from functools import lru_cache
from datetime import datetime, timedelta
import json

class CachedUserProfile:
    def __init__(self, ttl_seconds=300):
        self.cache = {}
        self.ttl_seconds = ttl_seconds

    def get(self, user_id):
        if user_id in self.cache:
            cached_data, timestamp = self.cache[user_id]
            if datetime.now() - timestamp < timedelta(seconds=self.ttl_seconds):
                return cached_data
            else:
                del self.cache[user_id]
        return None

    def set(self, user_id, data):
        self.cache[user_id] = (data, datetime.now())

    def invalidate(self, user_id):
        if user_id in self.cache:
            del self.cache[user_id]

profile_cache = CachedUserProfile(ttl_seconds=300)

@app.get("/api/users/{user_id}")
def get_user_profile(user_id: str):
    cached = profile_cache.get(user_id)
    if cached:
        return {"data": cached, "source": "cache"}

    user = db.get_user(user_id)
    profile_cache.set(user_id, user)
    return {"data": user, "source": "database"}
